<template>
  <div class="selector-wrap">
    <div class="selector-bg"></div>

    <div class="slide-scroll">
      <div class="slide-inner">
        <h1 class="main-title">Выберете рынок и актив, на котором Вы будете тестировать свои стратегии</h1>
        <p class="sub-title">
          Вам дается исторический график цен за 2015-2025 гг.
          После старта игры цена продолжает изменяться в реальном времени на основе модели случайного блуждания.
        </p>

        <div class="promo-box">
          <p class="promo-label">Три актива</p>
          <div class="cards-row">
            <div
              v-for="asset in assets" :key="asset.key"
              class="asset-card"
              :class="{ selected: selectedKey === asset.key }"
              @click="selectedKey = asset.key"
              :style="{ '--asset-border-color': asset.borderColor, '--asset-selected-bg': asset.selectedBg }"
            >
              <div class="asset-category">{{ asset.category }}</div>
              <div class="asset-card-body">
                <div class="asset-name">{{ asset.name }}</div>
                <div class="asset-card-img">
                  <img v-if="asset.img" :src="asset.img" :alt="asset.name" class="asset-img">
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>

    <div class="slide-footer">
      <button class="nav-btn" @click="$router.push('/')">Назад</button>
      <button class="nav-btn nav-btn-primary" :disabled="!selectedKey" @click="play">Играть</button>
    </div>
  </div>
</template>

<script>
import sp500Img from '@/assets/icons/sp500.png'
import goldImg    from '@/assets/icons/gold.png'
import eurusdImg  from '@/assets/icons/eurusd.png'

export default {
  name: 'AssetSelectorView',
  data() {
    return {
      selectedKey: null,
      assets: [
        { key: 'SPX',    name: 'S&P 500',  category: 'Фондовый рынок', img: sp500Img,  borderColor: 'var(--color-market-blue)', selectedBg: 'rgba(100,169,220,0.13)' },
        { key: 'EURUSD', name: 'EUR/USD',  category: 'Валютный рынок',  img: eurusdImg, borderColor: 'var(--color-market-gray)', selectedBg: 'rgba(185,189,199,0.18)' },
        { key: 'Gold',   name: 'Золото',   category: 'Товарный рынок',  img: goldImg,   borderColor: 'var(--color-accent)',      selectedBg: 'rgba(170,197,111,0.13)' },
      ]
    }
  },
  mounted() {
    const hasResult   = localStorage.getItem('hasResult')   === 'true'
    const levelEnded  = localStorage.getItem('levelEnded')  === 'true'
    const level       = Number(localStorage.getItem('level') || 0)
    const hasProgress = localStorage.getItem('hasProgress') === 'true'
    if (hasResult) {
      this.$router.push('/res')
    } else if (levelEnded && level === 0) {
      this.$router.push('/mode')
    } else if (hasProgress) {
      this.$router.push('/play')
    }
  },
  methods: {
    play() {
      if (!this.selectedKey) return
      const asset = this.selectedKey
      localStorage.clear()
      localStorage.setItem('selectedAsset', asset)
      localStorage.setItem('level', '0')
      this.$router.push('/instructions')
    }
  }
}
</script>

